def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    threshold = 4000
    count = sum(1 for value in values if value > threshold)
    return {
        "value": count,
        "trace": {
            "threshold": threshold,
            "years_exceeding_threshold": count,
            "output_meta": {"currency": None, "scale": None, "unit": "years"}
        }
    }
